(function(){
'use strict';
const G=window.GuildGame, KEY='contract-operations-playtest-031-v1';
const $=id=>document.getElementById(id);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const credits=n=>Number(n).toLocaleString('en-US');
let state,storage=true,tab='contracts',activeOfficer='command',modalType=null,dialogData=null;
try{const raw=localStorage.getItem(KEY);const v=raw&&JSON.parse(raw);state=v&&v.schema==='contract-operations-browser-1'&&v.rules==='0.3.1'&&Array.isArray(v.mercs)&&Array.isArray(v.board)?v:G.fresh();}catch{state=G.fresh();storage=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storage=false;}if($('save-status'))$('save-status').textContent=storage?'Progress is saved in this browser. Export notes to share here.':'Browser saving is unavailable. Export notes before closing.';}
function notify(t,bad=false){$('notice').className='notice shown'+(bad?' error':'');$('notice').textContent=t;}
function run(fn){try{fn();save();render();return true;}catch(e){notify(e.message,true);const node=$('modal-error');if(node)node.textContent=e.message;return false;}}
function statusName(m){if(m.status==='Onboarding')return 'Onboarding · T'+m.readyAt;if(m.status==='Recovering')return 'Recovering · until T'+m.readyAt;if(m.status==='Training'){let c=state.cohorts.find(c=>c.active&&c.ids.includes(m.id));return 'Training · block '+(c?.block||1);}return m.status;}
function isActionDisabled(){const o=G.officer(state,activeOfficer);return state.phase!=='activity'||state.actions<1||o.used>=2;}
function button(label,action,extra='',disabled=false,css='primary'){return `<button class="${css}" data-do="${action}" ${extra} ${disabled?'disabled':''}>${label}</button>`;}
function badge(kind,text){return `<span class="badge ${esc(kind)}">${esc(text)}</span>`;}
function render(){
 $('turn-number').textContent=String(state.turn).padStart(2,'0');$('phase-caption').textContent={activity:'Activity · Plan this interval',upkeep:'Upkeep · Settle the last interval',event:'Events · A visible monthly choice',advancement:'Advancement · Close the turn'}[state.phase];
 const crew=state.mercs.filter(m=>!['Candidate','Expired'].includes(m.status));const avail=crew.filter(G.available).length;const arrears=state.arrears.reduce((a,b)=>a+b.amount,0);const nextBill=150+state.facilities.reduce((a,f)=>a+G.V.facilities[f.type].monthly,0);const repTier=G.V.reputation_tiers.find(t=>state.reputation>=t[1]&&state.reputation<=t[2])[0];
 $('stats').innerHTML=`<div class="stat"><p class="eyebrow">TREASURY</p><div class="stat-value">${credits(state.cash)}<small>credits</small></div><div class="stat-bottom ${arrears?'bad':''}">${arrears?credits(arrears)+' owed in arrears':'Next routine bill: '+credits(nextBill)+' · wages separate'}</div></div><div class="stat"><p class="eyebrow">GUILD DEVELOPMENT</p><div class="stat-value">Level ${state.guildLevel}</div><div class="stat-bottom">${state.guildXP}/1,000 XP${state.pendingGuildXP?' · +'+state.pendingGuildXP+' pending':''}</div><div class="bar"><i style="width:${Math.min(100,(state.guildXP+state.pendingGuildXP)/10)}%"></i></div></div><div class="stat"><p class="eyebrow">REPUTATION</p><div class="stat-value">${state.reputation>=0?'+':''}${state.reputation}<small>${esc(repTier)}</small></div><div class="stat-bottom">Failure hurts public trust. Paying crew affects Loyalty.</div></div><div class="stat"><p class="eyebrow">PERSONNEL</p><div class="stat-value">${avail}<small>available / ${crew.length} roster</small></div><div class="stat-bottom">${state.metrics.completed} completed · ${state.metrics.failed} failed</div></div>`;
 const phaseIndex={upkeep:0,activity:3,event:4,advancement:5}[state.phase];$('timeline').innerHTML=['01 Upkeep','02 Budget','03 Commerce','04 Activity','05 Events','06 Advancement'].map((x,i)=>`<span class="${i===phaseIndex?'current':i<phaseIndex?'done':''}">${x}</span>`).join('');
 $('activity-controls').classList.toggle('hidden',state.phase!=='activity');$('active-officer').innerHTML=state.officers.map(o=>`<option value="${o.id}" ${o.id===activeOfficer?'selected':''}>${esc(o.name)} · ${2-o.used}/2 actions</option>`).join('');$('officer-note').textContent=G.officer(state,activeOfficer).used>=2&&state.actions>0?'No capacity left — choose another officer.':G.officer(state,activeOfficer).role;$('pay-arrears').classList.toggle('hidden',!arrears);
 $('capacity').innerHTML=`<div class="action-number">${state.actions}<span>of ${G.V.guild_actions[state.guildLevel]} actions</span></div><div class="action-pips">${Array.from({length:G.V.guild_actions[state.guildLevel]},(_,i)=>`<i class="${i>=state.actions?'spent':''}"></i>`).join('')}</div>${state.officers.map(o=>`<div class="officer-line"><b>${esc(o.name)}</b><span>${2-o.used}/2 capacity</span></div>`).join('')}<p class="table-note" style="color:#b6c8bd">Two portfolios do not grant extra actions. Unused capacity expires.</p>`;
 $('crew-glance').innerHTML=crew.slice(0,10).map(m=>`<div class="crew-line"><span class="avatar ${esc(m.color)}">${esc(m.name.slice(0,2).toUpperCase())}</span><div><b>${esc(m.name)}</b><small>Level ${m.level} · Loyalty ${m.loyalty}</small></div><span class="crew-status">${esc(m.status)}</span></div>`).join('');
 if($('feedback').value!==state.feedback)$('feedback').value=state.feedback||'';
 $('board-count').textContent=state.board.filter(c=>['Offer','Accepted'].includes(c.status)).length;
 document.querySelectorAll('.tabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));
 renderStage();renderWorkspace();save();
}
function renderStage(){let html='';if(state.phase==='upkeep'){const j=G.nextJob(state);if(j){html=`<section class="stage-card"><p class="eyebrow">UPKEEP / SCHEDULED RETURN</p><h2>${esc(j.contract.name)}</h2><p>Your leads were locked at departure. Roll each phase once; the crew’s relevant supporters contribute automatically. All receipts will arrive before routine bills.</p><div class="roll-grid">${j.quote.checks.map((c,p)=>{const r=j.rolls[p];return `<div class="phase-result ${p===j.rolls.length?'active':''}"><span>${p+1} · ${esc(c.phase)}</span>${r?`<strong class="${r.degree<2?'roll-fail':''}">${r.face} +${r.actualModifier}</strong><small>DC${r.dc} · ${esc(G.names[r.degree])}</small>`:`<strong>—</strong><small>${esc(c.leadName)} · ${esc(c.skill)} +${c.modifier} / DC${c.dc}</small>`}</div>`;}).join('')}</div>${button('Roll '+G.phases[j.rolls.length]+' · d20','roll')}<p class="table-note">${G.V.contracts[j.contract.kind].required_successes} successful phases required${j.contract.essential!==undefined?' · '+G.phases[j.contract.essential]+' Essential':''}. Critical Success counts once. No fourth check.</p></section>`;}else{html=`<section class="stage-card"><p class="eyebrow">UPKEEP / RESULTS & OBLIGATIONS</p><h2>The last interval is settled.</h2><p>Client receipts arrived before routine successful payroll and headquarters bills. Finish these decisions before the new action budget opens.</p>${state.upkeep.choices.map(c=>upkeepChoice(c)).join('')}${!state.upkeep.choices.length?`<div class="button-row">${button('Open this turn’s Activity →','finish-upkeep')}</div>`:''}</section>`;}}
 else if(state.phase==='event'){const e=state.event;html=`<section class="stage-card"><p class="eyebrow">EVENTS / ONE VISIBLE MONTHLY EVENT</p><h2>${esc(e.title)}</h2><p>${esc(e.text)}</p><div class="button-row">${button(e.type==='lead'?'Keep the lead':e.type==='community'?'Accept the introduction':'Acknowledge the concern','event-accept')}${e.type!=='concern'?button('Let it pass','event-pass','',false,'quiet'):''}</div><p class="table-note">Immediate choices are free. Substantial follow-up uses next turn’s actions.</p></section>`;}
 else if(state.phase==='advancement'){html=`<section class="stage-card"><p class="eyebrow">ADVANCEMENT / GUILD TURN ${state.turn} COMPLETE</p><h2>${state.turn>=6?'Your guild is taking shape.':'Close the books. Plan the next month.'}</h2><p>Guild Level ${state.guildLevel} · ${state.guildXP}/1,000 XP. ${state.featChoices?'You have '+state.featChoices+' Guild Feat choice'+(state.featChoices>1?'s':'')+' available. You may choose now or save them.':'Organizational XP has settled. New capacity applies next boundary.'}</p>${state.featChoices?`<div class="feat-grid">${G.availableGuildFeats(state).map(f=>`<div class="feat-choice"><h3>${esc(f.name)}</h3><p>${esc(f.text)}</p>${button('Choose feat','guild-feat',`data-id="${f.id}"`,false,'secondary')}</div>`).join('')}</div>`:''}<div class="button-row">${button('Advance 30 days · Turn '+(state.turn+1)+' →','advance')}${state.turn>=6?button('Copy first-season notes','export','',false,'quiet'):''}</div><p class="table-note">Available offers and recruits last only through their printed expiry. No newly started work resolves at this boundary.</p></section>`;}
 $('stage-panel').innerHTML=html;
}
function upkeepChoice(c){if(c.type==='failedPay'){const j=state.jobs.find(j=>j.id===c.job);return `<div class="choice-box"><h3>${esc(j.contract.name)} · contractor pay</h3><p>No client payout. Choose actual funded wages; the waived remainder is not default debt. This does not offset Reputation loss.</p><div class="button-row">${button('Full · '+credits(j.quote.pay)+' · Loyalty +10','upkeep-choice',`data-id="${c.id}" data-value="full"`,state.cash<j.quote.pay,'secondary')}${button('Half · '+credits(G.round(j.quote.pay*.5))+' · +4','upkeep-choice',`data-id="${c.id}" data-value="half"`,state.cash<G.round(j.quote.pay*.5),'secondary')}${button('None · Loyalty −10','upkeep-choice',`data-id="${c.id}" data-value="none"`,false,'quiet')}</div></div>`;}if(c.type==='mvp'){const j=state.jobs.find(j=>j.id===c.job);return `<div class="choice-box"><h3>${esc(j.contract.name)} · name one MVP</h3><p>Choose a lead or supporter with a recorded material contribution. Completion grants equal base XP; MVP adds 50 to one operative.</p><div class="button-row">${c.eligible.map(i=>button(esc(G.merc(state,i).name),'upkeep-choice',`data-id="${c.id}" data-value="${i}"`,false,'secondary')).join('')}${button('No MVP','upkeep-choice',`data-id="${c.id}" data-value="none"`,false,'quiet')}</div></div>`;}const t=state.cohorts.find(t=>t.id===c.cohort);const cost=G.trainingCost(state,t.ids),next=G.round(150*(1+Math.min(.1*t.block,.5)));return `<div class="choice-box"><h3>Training cohort · continue or release</h3><p>${t.ids.map(i=>esc(G.merc(state,i).name)).join(', ')}. Next block: ${next} XP each, ${cost} credits; no new Guild Action. Releasing makes them Available and ends the streak.</p><div class="button-row">${button('Continue · '+cost+' credits','upkeep-choice',`data-id="${c.id}" data-value="continue"`,state.cash<cost,'secondary')}${button('Release the cohort','upkeep-choice',`data-id="${c.id}" data-value="stop"`,false,'quiet')}</div></div>`;}
function renderWorkspace(){if(tab==='contracts')renderContracts();else if(tab==='people')renderPeople();else if(tab==='development')renderDevelopment();else renderLog();}
function renderContracts(){const active=state.board.filter(c=>['Offer','Accepted'].includes(c.status));const accepted=active.filter(c=>c.status==='Accepted'),offers=active.filter(c=>c.status==='Offer');let html=`<div class="section-heading"><h2>The contract board</h2><span class="small-label">${state.freeAcquisition?'FREE ACQUISITION / A/B':'ONE-ACTION ACQUISITION'}</span></div>`;if(accepted.length)html+=`<section class="subsection"><div class="subsection-head"><h3>Accepted · awaiting crew</h3><p>Deployment is routine.</p></div><div class="contracts">${accepted.map(contractCard).join('')}</div></section>`;html+=`<section class="subsection"><div class="contracts">${offers.length?offers.map(contractCard).join(''):`<div class="empty"><h3>No available offers.</h3><p>Work the Network for leads, or wait for an event/contact. The board does not refill automatically.</p>${button('Search for contract leads','network-contracts','',isActionDisabled(),'secondary')}</div>`}</div></section>`;const underway=state.jobs.filter(j=>!j.settled);if(underway.length)html+=`<section class="subsection"><h3>Operating this interval</h3>${underway.map(j=>`<div class="panel"><span class="badge deployed">DEPLOYED</span><h3>${esc(j.contract.name)}</h3><p class="table-note">Returns Turn ${j.due} · ${j.ids.map(i=>esc(G.merc(state,i).name)).join(', ')} · frozen wages ${j.quote.pay} · successful client payout ${j.quote.payout}</p></div>`).join('')}</section>`;html+=`<section class="subsection"><div class="action-grid"><div class="action-card"><h3>Work the Network</h3><p>Diplomacy generates 0/1/2/3 contract leads by degree. Securing a lead is a separate decision.</p><div class="price">1 action <span>· no cash cost</span></div>${button('Find leads','network-contracts','',isActionDisabled(),'secondary')}</div><div class="action-card"><h3>Broker Exclusive Deal</h3><p>Trained Diplomacy and Friendly Reputation. Seek a harder, richer, deadline-bound offer. Never accept without ready personnel.</p><div class="price">1 action · 50 credits</div>${button('Pursue an exclusive','broker','',isActionDisabled()||state.reputation<20||!G.officer(state,activeOfficer).skills.Diplomacy||state.cash<50,'secondary')}</div></div></section>`;$('workspace').innerHTML=html;}
function contractCard(c){let card=G.V.contracts[c.kind],payout=G.round(12*G.wage(c.level)*card.payout_factor);let accepted=c.status==='Accepted';let waiver=c.kind==='standard'&&state.contacts.includes(c.client)&&!state.trustedUsed&&(state.guildFeats.includes('trusted')||state.guildFeats.includes('standing'));let canSecure=state.phase==='activity'&&(state.freeAcquisition||c.standing||!isActionDisabled()||waiver);return `<article class="contract ${accepted?'accepted':''}"><div class="contract-header">${badge(accepted?'accepted':c.kind,accepted?'Accepted':c.kind==='exclusive'?'Exclusive · Standard':c.kind)}<span class="level">LEVEL ${c.level}</span></div><h3>${esc(c.name)}</h3><div class="client">${esc(c.client)}</div><p style="margin-top:12px">${esc(c.description)}</p><div class="terms"><div><strong>${credits(payout)}</strong><small>credits on success · recommended crew</small></div><div style="text-align:right"><b>${card.required_successes} of 3</b><small>successful phases</small></div></div><div class="card-buttons">${accepted?button('Assign & deploy','deploy',`data-id="${c.id}"`,state.phase!=='activity') :button(state.freeAcquisition||c.standing?'Secure · free':waiver?'Secure · waiver available':'Secure · 1 action','secure',`data-id="${c.id}"`,!canSecure)}${button('Card details','details',`data-id="${c.id}"`,false,'quiet')}</div>${accepted?button('Digital Recon · 1 action','recon',`data-id="${c.id}"`,isActionDisabled()||!G.officer(state,activeOfficer).skills.Computers||!!c.preparation,'text-button'):''}<p class="risk-line">${accepted?'Deploy by Turn '+c.deployBy:'Offer through end of Turn '+c.expires} · crew 2 / 4 / 6 · min Squad Level ${Math.max(1,c.level-2)}${card.mandatory_recovery?' · recovery '+card.mandatory_recovery+' turn':''}${c.essential!==undefined?' · '+G.phases[c.essential]+' Essential':''}</p></article>`;}
function renderPeople(){const crew=state.mercs.filter(m=>!['Candidate','Expired'].includes(m.status));const candidates=state.mercs.filter(m=>m.status==='Candidate'&&m.expires>=state.turn);let html=`<div class="section-heading"><h2>People, not just a pool</h2><span class="small-label">EXPLICIT SKILLS / MONTHLY COMMITMENTS</span></div><div class="people-grid">${crew.map(personCard).join('')}</div><section class="subsection"><div class="subsection-head"><h3>Recruitment candidates</h3><p>Hiring costs an action. New hires start next turn.</p></div>${candidates.length?`<div class="people-grid">${candidates.map(personCard).join('')}</div>`:`<div class="empty"><p>No active candidates. A network search finds options; hiring each operative is separate.</p>${button('Find candidates','network-recruits','',isActionDisabled(),'secondary')}</div>`}</section><section class="subsection"><div class="action-grid"><div class="action-card"><h3>Run Training Drills</h3><p>Commit up to ${G.trainingCapacity(state)} Available operatives for 30 days. First block150 XP; consecutive bonuses cap at50%.</p><div class="price">1 action <span>· 50/cohort trainer +25/person</span></div>${button('Select a training cohort','train','',isActionDisabled()||!crew.some(G.available),'secondary')}</div><div class="action-card"><h3>Boost Morale</h3><p>Invest in Available or returned Recovering crew. Loyalty helps keep people committed; it does not erase failed-contract Reputation.</p><div class="price">1 action · 10 per person</div>${button('Recognize the crew','morale','',isActionDisabled(),'secondary')}</div><div class="action-card"><h3>Establish Recovery Protocol</h3><p>Trained Medicine. Treat returned Recovering staff now. Successful care can release them this Activity.</p><div class="price">1 action · 25 per person <span>· max four</span></div>${button('Arrange medical care','recover','',isActionDisabled()||!G.officer(state,activeOfficer).skills.Medicine||!crew.some(m=>m.status==='Recovering'),'secondary')}</div><div class="action-card"><h3>Work the Network</h3><p>Find a new set of candidates through Diplomacy. They remain hireable through the next turn, then move on.</p><div class="price">1 action <span>· no cash cost</span></div>${button('Search for recruits','network-recruits','',isActionDisabled(),'secondary')}</div></div></section>`;$('workspace').innerHTML=html;}
function personCard(m){let candidate=m.status==='Candidate';return `<article class="person"><div class="person-top"><span class="avatar ${esc(m.color)}">${esc(m.name.slice(0,2).toUpperCase())}</span><div><h3>${esc(m.name)}</h3><p>${esc(m.role)}</p></div></div>${badge(m.status,statusName(m))}<p class="bio">${esc(m.bio)}</p><div class="person-metrics"><b>Level ${m.level}</b><span>${credits(G.wage(m.level))}/assignment</span><span>Loyalty ${m.loyalty}</span></div><div class="bar"><i style="width:${m.xp/10}%"></i></div><div class="status-detail">${m.xp}/1,000 XP · listed skills ${G.rank(m.level)} · unlisted skills untrained</div><div class="skill-tags">${Object.keys(m.skills).map(k=>`<span>${esc(k)} +${G.skill(m,k)}</span>`).join('')}</div>${candidate?`<p class="status-detail">Hiring ${2*G.wage(m.level)} · expires end Turn ${m.expires} · starts next turn</p>${button('Recruit · 1 action','hire',`data-id="${m.id}"`,isActionDisabled()||state.cash<2*G.wage(m.level))}`:m.level>=5&&!m.leaderFeat?button('Choose Level 5 Leader Feat','leader-feat',`data-id="${m.id}"`,false,'secondary'):m.leaderFeat?`<p class="status-detail">Leader Feat: ${esc(G.leaderFeats.find(f=>f.id===m.leaderFeat).name)} · active only if appointed leader</p>`:''}</article>`;}
function renderDevelopment(){let active=state.projects.filter(p=>!p.done),slots=2-state.facilities.length-active.filter(p=>!p.repairId).length;let html=`<div class="section-heading"><h2>Build the operation</h2><span class="small-label">LEASED HQ / ${slots} SLOTS FREE</span></div><div class="panel"><h3>Guild Level ${state.guildLevel}</h3><p class="table-note">Shared pool ${G.V.guild_actions[state.guildLevel]} · concurrent projects ${G.V.project_capacity[state.guildLevel]} · 1,000 XP per Guild Level · feats at2,4,6,8,10</p><p class="table-note">Earned feats: ${state.guildFeats.length?state.guildFeats.map(id=>esc(G.guildFeats.find(f=>f.id===id).name)).join(', '):'none yet'}. Choose pending feats during Advancement.</p></div><div class="action-grid">${['training_suite','infirmary'].map(type=>{let q=G.facilityQuote(type),installed=state.facilities.some(f=>f.type===type),building=active.some(p=>p.type===type);let description=type==='training_suite'?'Six-person training cohorts instead of four. No XP-rate increase. Transferable1.':'Reduce phase-added recovery by one after actual return. Mandatory card recovery remains. Transferable2.';return `<div class="action-card"><h3>${type==='training_suite'?'Training Suite':'Infirmary'}</h3><p>${description}</p><div class="price">${credits(q.cost)} funded <span>· includes manager · ${q.turns} turn${q.turns>1?'s':''}</span></div><div class="status-detail">${q.overhead}/month after activation · one slot · 200 once-only Guild XP</div>${button(installed?'Installed':building?'Under construction':'Commission · 1 action','project',`data-type="${type}"`,isActionDisabled()||state.cash<q.cost||installed||building||slots<1||active.length>=G.V.project_capacity[state.guildLevel],'secondary')}</div>`;}).join('')}<div class="action-card"><h3>Promote the Guild</h3><p>A modest publicity effort. Actual officer Diplomacy versus organizational DC${G.administrativeDC(state)}; degrees change Reputation−1/0/+2/+4.</p><div class="price">1 action · 50 credits</div>${button('Promote the guild','promote','',isActionDisabled()||state.cash<50,'secondary')}</div><div class="action-card"><h3>Optimize Infrastructure</h3><p>Trained Crafting. Save10%/20% on one facility’s next overhead on Success/Critical Success. Does not discount the HQ lease.</p><div class="price">1 action <span>· no credit fee</span></div>${button('Plan maintenance','optimize','',isActionDisabled()||!G.officer(state,activeOfficer).skills.Crafting||!state.facilities.length,'secondary')}</div></div>`;if(active.length)html+=`<section class="subsection"><h3>Committed projects</h3>${active.map(p=>`<div class="panel"><h3>${esc(p.type.replaceAll('_',' '))}</h3><p class="table-note">Manager assigned · completes Turn ${p.due} · costs already funded · continuing is routine</p></div>`).join('')}</section>`;if(state.facilities.length)html+=`<section class="subsection"><h3>Active installations</h3>${state.facilities.map(f=>`<div class="panel"><b>${esc(f.type.replaceAll('_',' '))}</b> ${badge('accepted',f.condition)}<p class="table-note">Operational from Turn ${f.activeSince} · ${G.V.facilities[f.type].monthly}/month · slot reserved</p></div>`).join('')}</section>`;$('workspace').innerHTML=html;}
function renderLog(){let inflow=state.ledger.filter(e=>e.amount>0).reduce((a,e)=>a+e.amount,0),outflow=-state.ledger.filter(e=>e.amount<0).reduce((a,e)=>a+e.amount,0);$('workspace').innerHTML=`<div class="section-heading"><h2>Operations log</h2><button data-do="export" class="quiet">Copy notes</button></div><div class="ledger-summary"><div><b>${credits(inflow)}</b>client receipts</div><div><b>${credits(outflow)}</b>actual spending</div><div><b>${credits(state.cash)}</b>treasury</div></div><details class="panel"><summary>Cash ledger · every actual receipt and payment</summary><table class="ledger-table"><thead><tr><th>Turn</th><th>Entry</th><th>Credits</th></tr></thead><tbody>${state.ledger.slice().reverse().map(e=>`<tr><td>T${e.turn}</td><td>${esc(e.note)}</td><td class="${e.amount>0?'good-text':'bad-text'}">${e.amount>0?'+':''}${credits(e.amount)}</td></tr>`).join('')}</tbody></table><p class="table-note">Starting funds2,000 +receipts−actual spending=treasury. Arrears are recorded obligations, not negative cash.</p></details>${state.log.map(l=>`<article class="log-entry ${esc(l.kind)}"><span class="log-turn">TURN ${l.turn}</span><div><h3>${esc(l.title)}</h3><p>${esc(l.text)}</p></div></article>`).join('')}`;}
function show(title,html,kicker='GUILD OPERATIONS'){modalType=title;$('modal-kicker').textContent=kicker;$('modal-content').innerHTML=`<h2>${esc(title)}</h2>${html}<p id="modal-error" class="modal-error" role="alert"></p>`;if(!$('modal').open)$('modal').showModal();}
function close(){$('modal').close();modalType=null;dialogData=null;}
function dialogActions(label,action,extra=''){return `<div class="modal-actions">${button('Cancel','close','',false,'quiet')}${button(label,action,extra)}</div>`;}
function checkedIds(){return [...document.querySelectorAll('#modal input[name="crew"]:checked')].map(x=>x.value);}
function crewOptions(members,all=true){return `<div class="crew-select">${members.map(m=>`<label class="crew-option"><input type="checkbox" name="crew" value="${m.id}" ${all?'checked':''}><span><b>${esc(m.name)}</b><small>Level ${m.level} · ${esc(m.role)}</small></span></label>`).join('')}</div>`;}
function details(cid){const c=G.offer(state,cid),v=G.V.contracts[c.kind];show(c.name,`<p class="modal-description">${esc(c.description)}</p><p class="modal-description"><b>Standard NPC resolution.</b> ${v.required_successes} successful phases of3${c.essential!==undefined?'; '+G.phases[c.essential]+' must succeed':''}. Duration1 turn. Offer expires end Turn ${c.expires}. ${c.kind==='exclusive'?'Accepted completion deadline: next boundary; deploy immediately.':'Ordinary expiry alone has no Reputation penalty.'}</p><div class="quote-box">${c.skills.map((k,p)=>`<div class="check-line"><b>${G.phases[p]} · ${esc(k)}</b><span>base DC${G.V.level_dc[c.level]+v.dc_offset}</span></div>`).join('')}</div><p class="modal-description">Crew size min2 / recommended4 / max6. Recommended Level${c.level}; minimum Squad Level${Math.max(1,c.level-2)}. Squad Level=floor average; size adjusts DC by±1/person, cap±2. Base client cash ${credits(G.round(12*G.wage(c.level)*v.payout_factor))}; larger/overlevel squads can discount it, never increase it.</p><p class="modal-description">XP ${v.participation_xp} participation +${v.completion_xp} completion each. GuildXP ${v.guild_xp} on completion. Reputation +${v.reputation_success}/${v.reputation_failure}. Required recovery ${v.mandatory_recovery} turn${v.mandatory_recovery===1?'':'s'}.</p><hr><p class="modal-description"><b>Phase consequences:</b> Critical Success +1 next phase; Failure−1 next; Critical Failure−2 all remaining and1 squad recovery. Recovery sources use the longest duration. Leads are locked before the first check; no support or overall roll.</p><div class="modal-actions">${button('Got it','close')}</div>`,'CONTRACT CARD');}
function secureDialog(cid){const c=G.offer(state,cid);const eligible=c.kind==='standard'&&state.contacts.includes(c.client)&&!state.trustedUsed&&(state.guildFeats.includes('trusted')||state.guildFeats.includes('standing'));show('Secure the contract',`<p class="modal-description"><b>${esc(c.name)}</b> · ${esc(c.client)}. ${state.freeAcquisition||c.standing?'Acquisition costs no action in this variant.':'Acquisition costs one shared action and one officer action.'} Deployment is a separate, routine staff assignment.</p>${eligible?`<label class="inline-choice"><input id="use-waiver" type="checkbox"><span>Use Trusted Client’s free acquisition this turn. One ordinary Standard contract from a known contact.</span></label>`:''}${c.kind==='exclusive'?'<p class="modal-description bad-text">Binding deadline: deploy now and finish next boundary. Accepting without ready staff will breach the contract.</p>':''}${dialogActions('Secure & plan crew','secure-confirm',`data-id="${cid}"`)}`);}
function deployDialog(cid){const c=G.offer(state,cid);const members=state.mercs.filter(m=>G.available(m)&&m.dispatchedTurn!==state.turn);dialogData={cid};show('Assign the operation',`<p class="modal-description">${esc(c.name)}. Select2–6 Available operatives, then declare all three leads. Their relevant supporters contribute automatically. Deployment spends no Guild Action.</p>${members.length?crewOptions(members):'<div class="empty">No Available crew. Finish training/recovery or wait for onboarding.</div>'}<div class="lead-grid">${c.skills.map((k,p)=>`<div class="form-row"><label for="lead-${p}">${G.phases[p]} · ${esc(k)}</label><select id="lead-${p}" data-lead="${p}"></select></div>`).join('')}</div><div id="leader-row" class="form-row"><label for="squad-leader">Optional Level5+ squad leader</label><select id="squad-leader"><option value="">No appointed leader</option></select></div><div id="deployment-quote" class="quote-box"></div>${dialogActions('Deploy squad · routine','deploy-confirm',`data-id="${cid}"`)}`,'DEPLOYMENT PLAN');updateDeployment(true);}
function updateDeployment(rebuild=false){if(!dialogData?.cid||!$('deployment-quote'))return;const c=G.offer(state,dialogData.cid),ids=checkedIds(),members=ids.map(i=>G.merc(state,i));if(rebuild){for(let p=0;p<3;p++){const sel=$('lead-'+p),old=sel.value;let best=members.slice().sort((a,b)=>G.skill(b,c.skills[p])-G.skill(a,c.skills[p]))[0]?.id;sel.innerHTML=members.map(m=>`<option value="${m.id}">${esc(m.name)} · +${G.skill(m,c.skills[p])}</option>`).join('');sel.value=ids.includes(old)?old:best||'';}let sel=$('squad-leader'),old=sel.value;const leaders=members.filter(m=>m.level>=5&&m.leaderFeat);sel.innerHTML='<option value="">No appointed leader</option>'+leaders.map(m=>`<option value="${m.id}">${esc(m.name)} · ${esc(G.leaderFeats.find(f=>f.id===m.leaderFeat).name)}</option>`).join('');sel.value=leaders.some(m=>m.id===old)?old:'';$('leader-row').classList.toggle('hidden',!leaders.length);}try{const q=G.quote(state,c,ids,[0,1,2].map(p=>$('lead-'+p).value),$('squad-leader').value||null);$('deployment-quote').className='quote-box';$('deployment-quote').innerHTML=`<div class="quote-metrics"><div><strong>${q.squadLevel}</strong><small>FLOOR-AVERAGE LEVEL</small></div><div><strong>${credits(q.payout)}</strong><small>SUCCESSFUL CLIENT CASH</small></div><div><strong>${credits(q.pay)}</strong><small>FROZEN SQUAD WAGES</small></div></div>${q.checks.map(r=>`<div class="check-line"><span>${esc(r.phase)} · ${esc(r.leadName)}</span><b>+${r.skillBonus} skill +${r.support} support${r.circumstance?' '+(r.circumstance>0?'+':'')+r.circumstance+' prepared':''} / DC${r.dc}</b></div>`).join('')}<p class="table-note">${G.V.contracts[c.kind].required_successes} successes needed. Supports use listed relevant ranks, capped. Failure pays no client cash; contractor pay remains your choice.</p>`;document.querySelector('[data-do="deploy-confirm"]').disabled=false;}catch(e){$('deployment-quote').className='quote-box error';$('deployment-quote').textContent=e.message;document.querySelector('[data-do="deploy-confirm"]').disabled=true;}}
function networkDialog(mode){show(mode==='recruits'?'Find recruitment candidates':'Find contract leads',`<p class="modal-description">${esc(G.officer(state,activeOfficer).name)} performs Diplomacy. One action; choose target level before rolling. Degrees produce0/1/2/3 ${mode==='recruits'?'candidates':'leads'}, with separate ${mode==='recruits'?'hiring':'securing'} actions afterward.</p><div class="form-row"><label for="search-level">Target level ·1–${Math.min(20,2*state.guildLevel+1)}</label><input id="search-level" type="number" value="1" min="1" max="${Math.min(20,2*state.guildLevel+1)}"></div>${dialogActions('Roll Diplomacy · 1 action','network-confirm',`data-mode="${mode}"`)}`);}
function selectPersonnel(mode){const eligible=state.mercs.filter(m=>mode==='train'?G.available(m):mode==='recover'?m.status==='Recovering':['Available','Recovering'].includes(m.status));const title={train:'Commit a training cohort',morale:'Recognize your people',recover:'Treat returned personnel'}[mode];show(title,`<p class="modal-description">${mode==='train'?'One action; commit up to '+G.trainingCapacity(state)+' Available personnel for one30-day block. Cost50/cohort trainer (less Training Cadre) +25/trainee. You can extend after completion without a new action.':mode==='recover'?'Trained Medicine; one action and25/person, maxfour. Success reduces remaining recovery by1; Critical Success by2. Eligible staff can be Available immediately.':'One action and10/person. Officer Diplomacy versus DC'+G.administrativeDC(state)+'. Loyalty changes−2/+2/+5/+8 by degree. Public Reputation is separate.'}</p>${eligible.length?crewOptions(eligible):'<div class="empty">No eligible personnel for this action.</div>'}<div id="personnel-cost" class="quote-box"></div>${dialogActions('Confirm · 1 action','personnel-confirm',`data-mode="${mode}"`)}`);dialogData={mode};updatePersonnel();}
function updatePersonnel(){if(!$('personnel-cost')||!dialogData?.mode)return;const n=checkedIds().length,mode=dialogData.mode;let cost=mode==='train'?G.trainingCost(state,checkedIds()):n*(mode==='recover'?25:10);$('personnel-cost').textContent=`${n} personnel · ${credits(cost)} credits funded now${mode==='train'?' · 150 XP each at next Upkeep':''}`;}
function setupDialog(){show('Start a matched playtest',`<p class="modal-description">Reset to four Level1 mercenaries, two PC officers,2,000 credits, two offers and three Guild Actions. Changing acquisition cost requires a fresh game. Export your current notes first if you want to retain them.</p><div class="form-row"><label for="seed">Scenario seed</label><input id="seed" type="number" value="${state.seed}" min="0" max="999999"></div><div class="form-row"><label for="acquisition">Contract acquisition</label><select id="acquisition"><option value="paid" ${!state.freeAcquisition?'selected':''}>One Guild Action · current baseline</option><option value="free" ${state.freeAcquisition?'selected':''}>Free · A/B comparison</option></select></div><p class="modal-description">The same seed repeats the same keyed rolls for matching turns/contracts. Different decisions can change schedules; this is a playable comparison, not a controlled population simulation.</p>${dialogActions('Reset & start playtest','reset-confirm')}`,'EXPERIMENT SETTINGS');}
function help(){show('Your first Guild Turn',`<p class="modal-description">You run the guild between adventures. The opening choice is simple: use your three shared actions to secure work, recruit, train, prepare, promote or build. Every action also needs an officer with capacity.</p><ol class="help-list"><li><b>Upkeep:</b> previously deployed jobs return; roll Insertion, Engagement and Extraction once each. Due receipts arrive before routine bills. Choose failed-job pay, MVP and training continuation.</li><li><b>Budget:</b> reset the shared pool and each officer’s two-action capacity. New hires become Available next turn.</li><li><b>Commerce:</b> the full game has property/financing choices; this focused demo shows the treasury but omits those transactions.</li><li><b>Activity:</b> secure a contract, then deploy Available staff without another action. Training and projects complete at later boundaries.</li><li><b>Events:</b> one visible monthly scenario; immediate choices are free. Substantial follow-up waits for next turn.</li><li><b>Advancement:</b> settle Guild XP and choose earned feats. Advance30 days to the next Upkeep.</li></ol><p class="modal-description"><b>Try this:</b> secure Dock Nine, assign the four starters, then use the remaining actions to find candidates and hire one. Or put half your crew in training and tackle an easier job later. Notice what you cannot do this month.</p><p class="modal-description">Play six months, then copy your notes back into chat. You can continue beyond six turns to test growth. Browser progress saves locally; exported notes preserve your decisions and dice. This demo does not adjudicate the complete tabletop subsystem.</p><div class="modal-actions">${button('Open for business','close')}</div>`,'PLAYTEST GUIDE');}
async function exportNotes(){const text=G.summary(state);try{await navigator.clipboard.writeText(text);notify('Playtest notes copied. Paste them into chat so we can discuss your decisions.');}catch{show('Copy your playtest notes',`<p class="modal-description">Select and copy this text, then paste it into chat.</p><textarea class="readonly-notes" rows="12" readonly>${esc(text)}</textarea><div class="modal-actions">${button('Done','close')}</div>`);}}
function download(){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([G.summary(state)],{type:'text/markdown;charset=utf-8'}));a.href=url;a.download='contract-operations-playtest-turn-'+state.turn+'.md';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Playtest notes downloaded. Your browser progress remains saved locally.');}
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b||b.disabled)return;if(b.dataset.tab){tab=b.dataset.tab;renderWorkspace();document.querySelectorAll('.tabs button').forEach(x=>x.classList.toggle('active',x.dataset.tab===tab));return;}const action=b.dataset.do;if(!action)return;const cid=b.dataset.id;switch(action){
 case 'close':close();break;case 'help':help();break;case 'settings':setupDialog();break;case 'export':exportNotes();break;case 'download':download();break;
 case 'details':details(cid);break;case 'secure':secureDialog(cid);break;case 'secure-confirm':{let use=$('use-waiver')?.checked||false;if(run(()=>G.secure(state,cid,activeOfficer,use))){close();deployDialog(cid);}break;}
 case 'deploy':deployDialog(cid);break;case 'deploy-confirm':{const ids=checkedIds(),leads=[0,1,2].map(p=>$('lead-'+p).value),leader=$('squad-leader').value||null;if(run(()=>G.deploy(state,cid,ids,leads,leader))){close();notify('Crew deployed. Resolve the contract next Upkeep, after30 days.');}break;}
 case 'network-recruits':networkDialog('recruits');break;case 'network-contracts':networkDialog('contracts');break;
 case 'network-confirm':{let mode=b.dataset.mode,level=Number($('search-level').value);if(run(()=>G.network(state,activeOfficer,mode,level))){close();tab=mode==='recruits'?'people':'contracts';render();notify(`${G.names[state.lastRoll.degree]}: d20${state.lastRoll.face} +${state.lastRoll.modifier} vs DC${state.lastRoll.dc}. See the new ${mode==='recruits'?'candidates':'leads'} below.`);}break;}
 case 'hire':if(run(()=>G.hire(state,cid,activeOfficer)))notify('Recruited. Available at next Guild Turn, after onboarding.');break;
 case 'train':case 'morale':case 'recover':selectPersonnel(action);break;
 case 'personnel-confirm':{let mode=b.dataset.mode,ids=checkedIds();if(run(()=>G[mode](state,ids,activeOfficer))){close();notify(mode==='train'?'Training funded. Staff remain unavailable until a completed block is released.':G.names[state.lastRoll.degree]+': see the resulting staff changes and operations log.');}break;}
 case 'promote':if(run(()=>G.promote(state,activeOfficer)))notify(`${G.names[state.lastRoll.degree]}: Reputation is now ${state.reputation}.`);break;
 case 'recon':{const c=G.offer(state,cid);show('Prepare one phase',`<p class="modal-description">Trained Computers · one action. Digital Recon adds−1/0/+1/+2 by degree to one named phase. Highest circumstance bonus only; no new mission check.</p><div class="form-row"><label for="recon-phase">Phase to prepare</label><select id="recon-phase">${G.phases.map((p,i)=>`<option value="${i}" ${i===1?'selected':''}>${p} · ${esc(c.skills[i])}</option>`).join('')}</select></div>${dialogActions('Conduct recon · 1 action','recon-confirm',`data-id="${cid}"`)}`);break;}
 case 'recon-confirm':{let p=Number($('recon-phase').value);if(run(()=>G.recon(state,cid,activeOfficer,p))){close();notify('Recon outcome recorded on this card. It applies once to the declared phase.');}break;}
 case 'broker':show('Pursue an Exclusive offer',`<p class="modal-description">Friendly Reputation, Trained Diplomacy,50 credits and one action. Outcomes:0/0/1/2 offers. A lead is not an accepted job; securing remains separate.</p><div class="form-row"><label for="search-level">Target level</label><input id="search-level" type="number" value="1" min="1" max="${Math.min(20,2*state.guildLevel+1)}"></div>${dialogActions('Broker the deal','broker-confirm')}`);break;
 case 'broker-confirm':{let level=Number($('search-level').value);if(run(()=>G.broker(state,activeOfficer,level))){close();notify('Brokerage resolved. Any generated offers appear on the board.');}break;}
 case 'project':{let type=b.dataset.type,q=G.facilityQuote(type);show('Commission '+type.replaceAll('_',' '),`<p class="modal-description">One action and${credits(q.cost)} credits funded now. The price includes${100*q.turns} for a qualified external manager over${q.turns} interval${q.turns>1?'s':''}. One HQ slot is reserved immediately; the project uses the shared cap. Your PC officer is not its manager.</p><div class="quote-box">Completes at Turn${state.turn+q.turns}. Monthly overhead${q.overhead} accrues after activation, payable the following boundary. New capability earns200 Guild XP once.</div>${dialogActions('Fund & commission','project-confirm',`data-type="${type}"`)}`);break;}
 case 'project-confirm':if(run(()=>G.project(state,b.dataset.type,activeOfficer))){close();notify('Project funded and manager committed. Continuing progress is routine.');}break;
 case 'optimize':show('Plan facility maintenance',`<p class="modal-description">Trained Crafting, one action, no credit fee. Target one owned installation’s next overhead. Savings are10%/20% on Success/Critical Success, rounded down.</p><div class="form-row"><label for="facility-target">Installation</label><select id="facility-target">${state.facilities.map(f=>`<option value="${f.id}">${esc(f.type.replaceAll('_',' '))} · ${G.V.facilities[f.type].monthly}/month</option>`).join('')}</select></div>${dialogActions('Optimize · 1 action','optimize-confirm')}`);break;
 case 'optimize-confirm':{let fid=$('facility-target').value;if(run(()=>G.optimize(state,fid,activeOfficer))){close();notify('Maintenance outcome recorded for that installation’s next monthly bill.');}break;}
 case 'leader-feat':show('Choose '+G.merc(state,cid).name+'’s Leader Feat',`<p class="modal-description">Earned at Level5. Choose once; only an appointed squad leader’s feat is active.</p><div class="action-grid">${G.leaderFeats.map(f=>`<div class="action-card"><h3>${esc(f.name)}</h3><p>${esc(f.text)}</p>${button('Choose','leader-confirm',`data-id="${cid}" data-value="${f.id}"`,false,'secondary')}</div>`).join('')}</div>`);break;
 case 'leader-confirm':if(run(()=>G.chooseLeaderFeat(state,cid,b.dataset.value)))close();break;
 case 'end':if(state.actions){show('Finish Activity with unused actions?',`<p class="modal-description">${state.actions} shared action${state.actions>1?'s remain':' remains'}. Unused actions expire; they do not become XP. You can leave them unused if staff, funds or officer capacity are the real limit.</p>${dialogActions('Proceed to Events','end-confirm')}`);}else run(()=>G.endActivity(state));break;
 case 'end-confirm':if(run(()=>G.endActivity(state)))close();break;
 case 'event-accept':run(()=>G.respondEvent(state,'accept'));break;case 'event-pass':run(()=>G.respondEvent(state,'pass'));break;
 case 'guild-feat':run(()=>G.chooseGuildFeat(state,cid));break;case 'advance':run(()=>G.advance(state));break;
 case 'roll':{if(run(()=>G.rollPhase(state)))notify('Phase result recorded. Critical Success and failure effects carry forward exactly as listed.');break;}
 case 'upkeep-choice':run(()=>G.choice(state,cid,b.dataset.value));break;
 case 'finish-upkeep':run(()=>G.finishUpkeep(state));break;case 'pay-arrears':run(()=>G.payArrears(state));break;
 case 'reset-confirm':{const seed=Number($('seed').value),free=$('acquisition').value==='free';if(!Number.isInteger(seed)||seed<0||seed>999999){$('modal-error').textContent='Choose an integer seed from0 to999999.';break;}state=G.fresh(seed,free);activeOfficer='command';tab='contracts';close();save();render();notify('Fresh playtest started. Seed '+seed+' · '+(free?'free':'paid')+' contract acquisition.');break;}
}});
document.addEventListener('change',e=>{if(e.target.id==='active-officer'){activeOfficer=e.target.value;render();}if(e.target.matches('#modal input[name="crew"]')){if(dialogData?.cid)updateDeployment(true);else updatePersonnel();}if(e.target.matches('#modal select[data-lead],#squad-leader'))updateDeployment(false);});
$('feedback').addEventListener('input',e=>{state.feedback=e.target.value;save();});$('close-modal').addEventListener('click',close);$('modal').addEventListener('close',()=>{modalType=null;dialogData=null;});
window.GuildPlaytest={getState:()=>JSON.parse(JSON.stringify(state)),render};render();
})();
